import {classPalettes,classPalette,classPaletteStyle,cleanClassPalette,paletteFromPixels} from './class-palettes.mjs';
import {escape} from './workspace-shared.js';
export function createClassAppearance({root,classId='',onChange=()=>{}}){
 let value=null,cover=null,previewURL='',generation=0;
 root.classList.add('class-appearance');root.innerHTML=`<h3>Class colours</h3><p>Give this class a palette for its calendar and workspace.</p><div class="class-palette-options" role="group" aria-label="Class colour palette"></div><label class="class-cover-upload">Use colours from a book cover<input type="file" accept="image/png,image/jpeg,image/webp" data-class-cover></label><div class="class-palette-preview"><img alt="Selected book cover" hidden><div><strong>Lesson preview</strong><span>Learning goals and classroom activities</span></div></div><p data-palette-status role="status"></p>`;
 const options=root.querySelector('.class-palette-options'),preview=root.querySelector('.class-palette-preview'),status=root.querySelector('[data-palette-status]');
 function render(){options.innerHTML=[{id:'auto',name:'Automatic'},...classPalettes,...(cover?[{...cover,name:'Book cover'}]:[])].map(p=>`<button type="button" data-palette="${p.id}" aria-pressed="${(value?.id||'auto')===p.id}" title="${escape(p.name)}"><span class="class-palette-chips" aria-hidden="true">${(p.colors||classPalette(null,classId).colors).map(c=>`<i data-chip-colour="${c}"></i>`).join('')}</span>${escape(p.name)}</button>`).join('');for(const chip of options.querySelectorAll('[data-chip-colour]'))chip.style.backgroundColor=chip.dataset.chipColour;preview.style.cssText=classPaletteStyle(value,classId);}
 options.onclick=event=>{const button=event.target.closest('[data-palette]');if(!button)return;value=button.dataset.palette==='auto'?null:button.dataset.palette==='cover'?cover:{id:button.dataset.palette};render();onChange();};
 root.querySelector('[data-class-cover]').onchange=async event=>{const file=event.target.files?.[0],token=++generation;if(!file)return;status.textContent='Finding colours…';let bitmap;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>12*1024*1024)throw Error('Choose a PNG, JPEG or WebP cover up to 12 MB.');bitmap=await createImageBitmap(file);if(token!==generation)return;const canvas=document.createElement('canvas');canvas.width=canvas.height=96;const context=canvas.getContext('2d',{willReadFrequently:true});context.drawImage(bitmap,0,0,96,96);cover=paletteFromPixels(context.getImageData(0,0,96,96).data);value=cover;if(previewURL)URL.revokeObjectURL(previewURL);previewURL=URL.createObjectURL(file);const image=preview.querySelector('img');image.src=previewURL;image.hidden=false;render();status.textContent='Palette ready. You can also choose a preset.';onChange();}catch(error){if(token===generation)status.textContent=error.message;}finally{bitmap?.close();}};
 return {fill(next,id=classId){generation++;classId=id;value=cleanClassPalette(next);cover=value?.id==='cover'?value:null;if(previewURL)URL.revokeObjectURL(previewURL);previewURL='';preview.querySelector('img').hidden=true;root.querySelector('[data-class-cover]').value='';status.textContent='';render();},value:()=>value,destroy(){generation++;if(previewURL)URL.revokeObjectURL(previewURL);}};
}
